window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[69]={"id":"069","numero":69,"titre":"Troubles psychiques de la grossesse et du post-partum","objectifs":[{"id":"69-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des principaux troubles concernés, y compris le post-partum blues et le trouble de stress post-traumatique en lien avec la grossesse","contenu":"<p>La <strong><span class=\"kw-def\">période périnatale</span></strong> s'étend de la <strong>conception</strong> à la <strong>1ʳᵉ année de l'enfant</strong>. C'est une <strong><span class=\"kw-alerte\">période de vulnérabilité particulière</span></strong> pour <span class=\"kw-clinique\">les</span> troubles psychiatriques : <strong>tous</strong> les troubles psychiatriques peuvent y survenir, sous deux formes — soit la <span class=\"kw-def\">décompensation d'un trouble préexistant</span> à la <span class=\"kw-ci\">grossesse</span>, soit un <span class=\"kw-def\">épisode inaugural</span> (pouvant ou non signer l'entrée dans un trouble psychiatrique chronique).</p>\n      <p><span class=\"kw-clinique\">Les</span> <strong>principales entités</strong> à savoir définir :</p>\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Post-partum blues</span></strong><br><em>(ou baby blues)</em></td>\n            <td><span class=\"kw-clinique\">État adaptatif physiologique transitoire</span> aux réaménagements affectifs liés à l'accouchement — survient à <span class=\"kw-chiffre\">J2-J5</span>, pic au <span class=\"kw-chiffre\">3ᵉ jour</span>. <strong>Ce n'est PAS un trouble psychiatrique</strong> ; c'est le <span class=\"kw-def\">diagnostic différentiel</span> classique de l'EDC du post-partum.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">EDC du post-partum</span></strong></td>\n            <td><span class=\"kw-etio\">Épisode dépressif caractérisé</span> survenant dans l'<span class=\"kw-chiffre\">année suivant l'accouchement</span> — le post-partum est la <span class=\"kw-alerte\">période à risque maximal de dépression chez la femme</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Psychose puerpérale</span></strong></td>\n            <td>Terme regroupant <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">épisodes psychotiques brefs</span> ET les <span class=\"kw-def\">épisodes thymiques</span> (<span class=\"kw-etio\">dépression</span> ou manie) <strong>avec caractéristiques psychotiques</strong> du post-partum. <span class=\"kw-alerte\">Urgence psychiatrique.</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">TSPT</span></strong> lié à la <span class=\"kw-ci\">grossesse</span></td>\n            <td><span class=\"kw-etio\">Trouble de stress post-traumatique</span> faisant suite à un <span class=\"kw-clinique\">accouchement vécu comme traumatique</span> (accouchement en <span class=\"kw-alerte\">urgence</span>, complications obstétricales) : flash-backs, évitement, hypervigilance.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Déni de grossesse</span></strong></td>\n            <td><span class=\"kw-clinique\">Déni partiel</span> = non-prise de conscience de la <span class=\"kw-ci\">grossesse</span> à partir de <span class=\"kw-chiffre\">≥ 22 SA</span> ; <span class=\"kw-clinique\">déni total</span> = jusqu'à l'accouchement. À <strong>différencier de la dissimulation volontaire</strong> de la grossesse.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-etio\">post-partum blues</span> n'est <span class=\"kw-alerte\">pas un trouble psychiatrique</span> mais un état physiologique — il ne nécessite aucun traitement. Il ne devient un FR de trouble psychiatrique que s'il est <strong>trop intense</strong> ou <strong>trop prolongé</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble anxieux</em></p>","frequence":0},{"id":"69-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence","contenu":"<p>La période périnatale concentre un risque élevé de troubles psychiatriques. <span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">prévalences</span> et les <strong>périodes d'apparition</strong> à connaître :</p>\n      <table >\n        <thead>\n          <tr><th>Trouble</th><th><span class=\"kw-def\">Prévalence</span></th><th>Période d'apparition</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Troubles anxieux</span></strong> de la <span class=\"kw-ci\">grossesse</span></td><td><span class=\"kw-chiffre\">5-15 %</span></td><td>Plus fréquents aux <span class=\"kw-chiffre\">1er</span> et <span class=\"kw-chiffre\">dernier trimestres</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">EDC</span></strong> de la <span class=\"kw-ci\">grossesse</span></td><td><span class=\"kw-chiffre\">10 %</span></td><td>Durant la <span class=\"kw-ci\">grossesse</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Déni de grossesse</span></strong></td><td><span class=\"kw-chiffre\">3/1000</span></td><td>Déni partiel à partir de <span class=\"kw-chiffre\">≥ 22 SA</span> ; déni total jusqu'à l'accouchement</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Post-partum blues</span></strong></td><td><span class=\"kw-chiffre\">30-80 %</span></td><td><span class=\"kw-chiffre\">J2-J5</span> après l'accouchement, pic au <span class=\"kw-chiffre\">3ᵉ jour</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">EDC du post-partum</span></strong></td><td><span class=\"kw-chiffre\">15 %</span></td><td>Survient <span class=\"kw-chiffre\">≤ 1 an</span>, pic entre <span class=\"kw-chiffre\">3-6 semaines</span> post-partum</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Épisode maniaque</span></strong> du post-partum</td><td><span class=\"kw-chiffre\">1/1000</span></td><td>Début <span class=\"kw-clinique\">brutal</span>, dans <span class=\"kw-clinique\">les</span> semaines après l'accouchement (parfois dès le 3ᵉ trimestre)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Épisode psychotique bref</span></strong></td><td><span class=\"kw-chiffre\">1-2/1000</span></td><td>Dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">≤ 4 premières semaines</span>, pic de fréquence à <span class=\"kw-chiffre\">J10</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le <strong>post-partum</strong> est la <span class=\"kw-alerte\">période à risque maximal de dépression chez la femme</span>. <span class=\"kw-clinique\">Les</span> complications psychiatriques sont <strong>plus nombreuses dans le post-partum</strong> que pendant la <span class=\"kw-ci\">grossesse</span>, dominées par les <span class=\"kw-etio\">troubles de l'humeur</span>.</div>","frequence":1},{"id":"69-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque prédisposant à un trouble psychique de la grossesse et du post partum","contenu":"<p>Le <span class=\"kw-def\">dépistage</span> des FR doit être <strong>le plus précoce possible</strong> (médecin traitant, obstétricien, sage-femme, PMI, psychiatre). L'<strong><span class=\"kw-def\">entretien prénatal précoce</span></strong> est proposé <span class=\"kw-alerte\">systématiquement au 4ᵉ mois de grossesse</span>. Trois grandes catégories de <span class=\"kw-def\">facteurs de risque</span> :</p>\n      <p><strong>FR psychiatriques</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">ATCD de troubles psychiatriques</span> personnels ou familiaux</li>\n        <li><span class=\"kw-etio\">Trouble lié à l'usage de substances</span>, en particulier le <strong>trouble lié à l'usage de l'<span class=\"kw-etio\">alcool</span></strong></li>\n      </ul>\n      <p><strong>Facteurs gynécologiques et obstétricaux</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Âge</span> : <span class=\"kw-ci\">grossesse</span> <span class=\"kw-chiffre\">&lt; 20 ans</span> ou <span class=\"kw-chiffre\">&gt; 35 ans</span></li>\n        <li><span class=\"kw-etio\">Primiparité</span> ; <span class=\"kw-ci\">grossesse</span> <span class=\"kw-etio\">non désirée</span></li>\n        <li>Découverte ou suspicion de <span class=\"kw-etio\">malformation</span> ou de <span class=\"kw-etio\">pathologie fœtale</span></li>\n        <li><span class=\"kw-etio\">Grossesse compliquée</span> (<span class=\"kw-etio\">diabète gestationnel</span>, <span class=\"kw-etio\">HTA</span> gravidique)</li>\n        <li><span class=\"kw-etio\">Accouchement compliqué</span> (dystocique, césarienne en <span class=\"kw-alerte\">urgence</span>, anesthésie générale)</li>\n        <li><span class=\"kw-etio\">Prématurité</span> / petit poids de naissance</li>\n        <li><span class=\"kw-etio\">ATCD obstétricaux pathologiques</span> (mort in utero, malformation fœtale, IMG, pathologie de l'enfant)</li>\n      </ul>\n      <p><strong>Facteurs environnementaux</strong></p>\n      <ul>\n        <li>Mère <span class=\"kw-etio\">célibataire</span> / difficultés conjugales</li>\n        <li><span class=\"kw-etio\">Précarité socio-économique</span>, faible niveau d'éducation, <span class=\"kw-etio\">isolement social</span></li>\n        <li><span class=\"kw-etio\">ATCD d'abus ou de maltraitance</span> dans l'enfance</li>\n        <li><span class=\"kw-etio\">Facteurs culturels</span> concernant principalement <span class=\"kw-clinique\">les</span> femmes migrantes (langue, représentations culturelles et rituels différents autour de la maternité)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span></em></p>","frequence":0},{"id":"69-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités sémiologiques d’un trouble psychique en période anténatale","contenu":"<p>Pendant la <span class=\"kw-ci\">grossesse</span>, trois entités dominent — leur sémiologie a des <strong>spécificités</strong> à connaître.</p>\n      <p><strong><span class=\"kw-etio\">Troubles anxieux</span> de la <span class=\"kw-ci\">grossesse</span></strong> (<span class=\"kw-chiffre\">5-15 %</span>) — plus fréquents aux <span class=\"kw-chiffre\">1er</span> et <span class=\"kw-chiffre\">dernier trimestres</span> :</p>\n      <ul>\n        <li><strong>Thèmes</strong> : modifications corporelles ; risque de <span class=\"kw-clinique\">malformation du fœtus</span> ; angoisse de l'accouchement ; capacité à s'occuper du bébé</li>\n        <li><strong>Manifestations</strong> : <span class=\"kw-clinique\">irritabilité</span> ; <span class=\"kw-clinique\">crainte permanente</span> ; <span class=\"kw-clinique\">crises d'angoisse</span> ; <span class=\"kw-clinique\">obsessions</span> et <span class=\"kw-clinique\">rituels</span> ; conduites d'évitement ou de réassurance ; <span class=\"kw-clinique\">troubles du sommeil</span></li>\n      </ul>\n      <p><strong><span class=\"kw-etio\">Épisode dépressif caractérisé</span> de la <span class=\"kw-ci\">grossesse</span></strong> (<span class=\"kw-chiffre\">10 %</span>) — la symptomatologie n'est <strong>pas spécifique</strong> de la grossesse, à deux exceptions près qui sont <span class=\"kw-clinique\">les</span> éléments discriminants :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Culpabilité centrée sur le fœtus</span></li>\n        <li><span class=\"kw-clinique\">Sentiment d'incapacité maternelle</span></li>\n      </ul>\n      <p>L'intensité est le plus souvent <span class=\"kw-chiffre\">légère à moyenne</span>.</p>\n      <p><strong><span class=\"kw-etio\">Déni de grossesse</span></strong> (<span class=\"kw-chiffre\">3/1000</span>) — découverte de la <span class=\"kw-ci\">grossesse</span> souvent <span class=\"kw-clinique\">fortuite</span> ; cliniquement, peu ou pas de modifications corporelles habituelles :</p>\n      <ul>\n        <li>Aucune prise de poids</li>\n        <li>Poursuite de saignements à type de « règles »</li>\n        <li>Peu ou pas d'augmentation du volume des seins et de l'abdomen</li>\n      </ul>\n      <p><strong>Pas de profil de femme à risque</strong> : le déni de <span class=\"kw-ci\">grossesse</span> n'est <span class=\"kw-alerte\">pas lié à un ATCD de trouble psychiatrique</span> maternel, et il n'évolue <strong>pas vers un trouble psychiatrique</strong> (sauf trouble préexistant). <span class=\"kw-clinique\">Les</span> risques tiennent au <span class=\"kw-alerte\">manque de suivi médical</span> de la grossesse : retard de croissance intra-utérin (RCIU), malformations, accouchement en <span class=\"kw-alerte\">urgence</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-etio\">déni de grossesse</span> n'est <strong>pas une dissimulation volontaire</strong> et ne relève pas d'un profil psychiatrique particulier — ne pas le confondre avec une <span class=\"kw-ci\">grossesse</span> délibérément cachée.</div>\n      <p>Chez une patiente <strong>avec ATCD psychiatrique</strong>, la <span class=\"kw-ci\">grossesse</span> est un FR de <span class=\"kw-clinique\">décompensation d'un trouble de l'humeur</span> ou d'une <span class=\"kw-etio\">schizophrénie</span> ; <span class=\"kw-clinique\">les</span> symptômes sont alors ceux habituellement décrits dans ces tableaux.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 66 — Trouble anxieux</em></p>","frequence":1},{"id":"69-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités sémiologiques d’un trouble psychique en période post-natale","contenu":"<p><span class=\"kw-clinique\">Les</span> complications psychiatriques sont <strong>plus nombreuses dans le post-partum</strong> que pendant la <span class=\"kw-ci\">grossesse</span>, dominées par les <span class=\"kw-etio\">troubles de l'humeur</span>. Quatre tableaux à différencier :</p>\n      <table >\n        <thead>\n          <tr><th>Tableau</th><th>Délai · début</th><th>Sémiologie</th><th>Risque · <span class=\"kw-clinique\">évolution</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Post-partum blues</span></strong><br><em>(non psychiatrique)</em></td>\n            <td><span class=\"kw-chiffre\">J2-J5</span>, pic <span class=\"kw-chiffre\">J3</span> ; dure <span class=\"kw-chiffre\">1-10 jours</span></td>\n            <td><span class=\"kw-clinique\">Fatigue</span> ; <span class=\"kw-clinique\">labilité émotionnelle</span> (dysphorie) ; <span class=\"kw-clinique\">crises de larmes</span> ; <span class=\"kw-clinique\">irritabilité</span> ; crainte d'être délaissée</td>\n            <td>État <span class=\"kw-clinique\">physiologique</span> : <strong>pas de traitement</strong>. Si trop long / trop sévère → devient un FR de trouble psychiatrique</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">EDC du post-partum</span></strong></td>\n            <td>Survient <span class=\"kw-chiffre\">≤ 1 an</span>, pic <span class=\"kw-chiffre\">3-6 semaines</span></td>\n            <td>Humeur triste ; <span class=\"kw-clinique\">forte culpabilité</span> ; <span class=\"kw-clinique\">sentiment d'incapacité maternelle</span> ; <span class=\"kw-clinique\">minimisation / dissimulation</span> ; plaintes physiques au 1er plan ; anxiété (<span class=\"kw-clinique\">phobies d'impulsion</span>) ; aggravation <span class=\"kw-clinique\">vespérale</span> ; irritabilité</td>\n            <td><span class=\"kw-alerte\">Sous-diagnostiqué (50 %)</span> ; FR d'<span class=\"kw-clinique\">évolution</span> vers un <span class=\"kw-etio\">trouble bipolaire</span> et de récidive dépressive</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Épisode maniaque</span></strong> du post-partum</td>\n            <td>Début <span class=\"kw-clinique\">brutal</span>, semaines post-accouchement (parfois dès le 3ᵉ trimestre)</td>\n            <td>Manifestations maniaques ; <span class=\"kw-clinique\">éléments confusionnels</span> ; caractéristiques mixtes fréquentes ; caractéristiques psychotiques possibles</td>\n            <td>Pose le diagnostic de <span class=\"kw-etio\">trouble bipolaire</span> ; <span class=\"kw-alerte\">risque suicidaire et d'infanticide</span> ; récidive ~<span class=\"kw-chiffre\">50 %</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Épisode psychotique bref</span></strong><br><em>(psychose puerpérale)</em></td>\n            <td>Dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">≤ 4 semaines</span>, pic <span class=\"kw-chiffre\">J10</span> ; début brutal</td>\n            <td>Idées délirantes à <span class=\"kw-clinique\">mécanismes polymorphes</span>, centrées sur la maternité / le bébé ; <span class=\"kw-clinique\">symptômes confusionnels</span> ; <span class=\"kw-clinique\">labilité émotionnelle</span></td>\n            <td>Évolue dans la majorité des cas vers un <span class=\"kw-etio\">trouble bipolaire</span> (parfois <span class=\"kw-etio\">schizophrénie</span>) ; <span class=\"kw-alerte\">risque suicidaire et d'infanticide</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> L'<span class=\"kw-etio\">épisode maniaque</span> et l'<span class=\"kw-etio\">épisode psychotique bref</span> du post-partum exposent à un <span class=\"kw-alerte\">risque majeur de suicide et d'infanticide</span> — ce sont des urgences psychiatriques imposant l'<span class=\"kw-alerte\">hospitalisation</span>.</div>\n      <p><strong><span class=\"kw-etio\">Troubles anxieux</span> du post-partum</strong> — isolés ou associés à d'autres tableaux. Deux formes à connaître :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Phobie d'impulsion</span></strong> : angoisses de passage à l'acte à l'égard du bébé, pouvant aller jusqu'à la <span class=\"kw-clinique\">phobie d'infanticide</span>. La mère <strong>reconnaît le caractère déraisonnable</strong> de ses pensées (<span class=\"kw-clinique\">insight conservé</span>).</li>\n        <li><strong><span class=\"kw-etio\">TSPT</span></strong> : <span class=\"kw-chiffre\">2 %</span> des femmes à <span class=\"kw-chiffre\">6 mois</span> ; survient après un <span class=\"kw-clinique\">accouchement en urgence</span> et/ou avec <span class=\"kw-clinique\">complications obstétricales</span>. Manifestations : <span class=\"kw-clinique\">flash-backs</span>, <span class=\"kw-clinique\">évitement</span> des situations liées à l'accouchement, <span class=\"kw-clinique\">hypervigilance</span>. <span class=\"kw-def\">Comorbidité</span> dépressive fréquente.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La <span class=\"kw-etio\">phobie d'impulsion</span> n'est <span class=\"kw-alerte\">PAS un FR de passage à l'acte hétéro-agressif</span> : l'insight est conservé. À ne pas confondre avec <span class=\"kw-clinique\">les</span> idées délirantes centrées sur le bébé d'une psychose puerpérale, où le risque d'infanticide est réel.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble anxieux · 353 — Risque et conduite suicidaire</em></p>","frequence":4},{"id":"69-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels psychiatriques et non psychiatriques spécifiques à la périnatalité","contenu":"<p>Tout tableau psychiatrique de la périnatalité — en particulier un <span class=\"kw-alerte\">tableau pseudo-confusionnel du post-partum</span> — impose d'évoquer deux ordres de diagnostics différentiels.</p>\n      <p><strong>Diagnostics différentiels psychiatriques</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Les</span> autres <span class=\"kw-def\">troubles psychiatriques</span> de la périnatalité entre eux (un épisode maniaque peut être confondu avec une psychose puerpérale, et inversement)</li>\n        <li>Distinction <span class=\"kw-etio\">post-partum blues</span> (physiologique) ↔ <span class=\"kw-etio\">EDC du post-partum</span> (trouble psychiatrique)</li>\n        <li><span class=\"kw-etio\">Intoxication par une substance psychoactive</span></li>\n      </ul>\n      <p><strong>Diagnostics différentiels non psychiatriques</strong> — causes organiques à <span class=\"kw-alerte\">éliminer en priorité</span>, à évoquer en post-partum :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Thrombophlébite cérébrale</span> (thrombose veineuse cérébrale)</li>\n        <li><span class=\"kw-alerte\">Endométrite</span> et autres infections du post-partum</li>\n        <li><span class=\"kw-alerte\">Rétention placentaire</span></li>\n        <li>Causes toxiques / intoxication par une substance psychoactive</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Devant un tableau <span class=\"kw-clinique\">confusionnel</span> du post-partum, une <span class=\"kw-alerte\">cause organique</span> (thrombophlébite cérébrale, infection, rétention placentaire, intoxication) doit être éliminée <strong>avant</strong> de retenir un diagnostic psychiatrique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 343 — Etat confusionnel - trouble de conscience</em></p>","frequence":0},{"id":"69-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications spécifiques à la périnatalité d’un bilan complémentaire en urgence","contenu":"<p><span class=\"kw-clinique\">Les</span> indications d'un <strong>bilan complémentaire en <span class=\"kw-alerte\">urgence</span></strong> spécifiques à la périnatalité découlent directement des <strong>diagnostics différentiels non psychiatriques</strong> : devant tout tableau <span class=\"kw-clinique\">atypique</span>, <span class=\"kw-clinique\">confusionnel</span> ou d'installation <span class=\"kw-clinique\">brutale</span> du post-partum, une <span class=\"kw-alerte\">cause organique</span> doit être recherchée en urgence avant de conclure à un trouble psychiatrique.</p>\n      <table >\n        <thead>\n          <tr><th>Cause organique à éliminer</th><th>Orientation du bilan en urgence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Thrombophlébite cérébrale</span></td><td>Imagerie cérébrale avec exploration veineuse</td></tr>\n          <tr><td><span class=\"kw-alerte\">Endométrite</span> / infection du post-partum</td><td>Bilan <span class=\"kw-etio\">infectieux</span> (évaluation clinique et <span class=\"kw-ttt\">biologique</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Rétention placentaire</span></td><td>Évaluation gynécologique et <span class=\"kw-imagerie\">échographie</span> pelvienne</td></tr>\n          <tr><td><span class=\"kw-etio\">Intoxication</span> par une substance psychoactive</td><td>Recherche de toxiques</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La fiche source du dossier <code>69-trouble-psychique-<span class=\"kw-ci\">grossesse</span>-postpartum/</code> ne détaille pas <span class=\"kw-clinique\">les</span> modalités précises (examens chiffrés, séquences d'imagerie) de ce bilan en <span class=\"kw-alerte\">urgence</span>. Le tableau ci-dessus reprend les orientations directement déductibles des diagnostics différentiels organiques de l'objectif précédent ; Kevin complétera les indications fines depuis le Collège de psychiatrie / le référentiel.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 343 — Etat confusionnel - trouble de conscience</em></p>","frequence":0},{"id":"69-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux spécifiques à la périnatalité","contenu":"<p>La prise en charge en périnatalité est <strong>multidisciplinaire</strong> (psychiatre, gynécologue-obstétricien, services de PMI) et repose sur un <span class=\"kw-def\">dépistage</span> précoce, avec l'<span class=\"kw-def\">entretien prénatal précoce</span> proposé au <span class=\"kw-chiffre\">4ᵉ mois</span> de <span class=\"kw-ci\">grossesse</span>.</p>\n      <p><strong><span class=\"kw-def\">Unités mère-enfant</span> (UME / UMB)</strong> — unités spécialisées dans la PEC de la pathologie mentale périnatale, indiquées si <span class=\"kw-clinique\">pathologie sévère</span> et/ou <span class=\"kw-etio\">environnement social précaire</span>. Trois objectifs :</p>\n      <ul>\n        <li>Soin de la <strong>mère</strong></li>\n        <li>Travail du <strong>lien mère-enfant</strong></li>\n        <li>Prévention des <strong>troubles du développement</strong> de l'enfant</li>\n      </ul>\n      <p><strong>Précautions des psychotropes pendant la <span class=\"kw-ci\">grossesse</span></strong></p>\n      <ul>\n        <li>Tous <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">psychotropes</span> traversent la <strong>barrière placentaire</strong> — évaluer le rapport bénéfice/risque pour chaque molécule</li>\n        <li><span class=\"kw-alerte\">3 premiers mois</span> = période la plus à risque (malformations) — éviter la prescription si possible</li>\n        <li>Prescrire à <strong>posologie minimale efficace</strong></li>\n        <li><span class=\"kw-alerte\">Pas d'arrêt brutal</span> à la découverte de la <span class=\"kw-ci\">grossesse</span> : risque de <span class=\"kw-ttt\">sevrage</span> ou de <span class=\"kw-alerte\">décompensation</span> du trouble sous-jacent</li>\n        <li>Recours au <span class=\"kw-def\">CRAT</span> (Centre de référence des agents tératogènes) en cas de doute</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span> absolue.</strong> L'<span class=\"kw-ci\">acide valproïque</span> est <strong>absolument <span class=\"kw-ci\">interdit</span></strong> pendant la <span class=\"kw-ci\">grossesse</span> et en 1ʳᵉ intention chez toute femme en âge de procréer.</div>\n      <p><strong>Anticipation de la <span class=\"kw-ci\">grossesse</span></strong> chez une patiente avec ATCD psychiatrique : projet individualisé, idéalement <span class=\"kw-clinique\">maladie stabilisée depuis ≥ 2 ans</span>, adaptation thérapeutique réalisée <strong>en amont</strong> de la grossesse, information de la patiente sur le risque de rechute.</p>\n      <p><strong>PEC des tableaux sévères</strong></p>\n      <table >\n        <thead>\n          <tr><th>Tableau</th><th>Prise en charge</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">EDC du post-partum</span></td><td><span class=\"kw-ttt\">ISRS</span> + psychothérapie (de soutien ou TCC) ; <span class=\"kw-alerte\">hospitalisation</span> en unité mère-enfant si forme sévère, idées suicidaires ou caractéristiques psychotiques</td></tr>\n          <tr><td><span class=\"kw-etio\">Épisode maniaque</span> du post-partum</td><td><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-ttt\">thymorégulateur</span> ± <span class=\"kw-ttt\">antipsychotique de 2ᵉ génération</span> ; <span class=\"kw-ttt\">ECT</span> si risque suicidaire et d'infanticide ; arrêt de l'<span class=\"kw-ci\">allaitement</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Psychose puerpérale</span></td><td><span class=\"kw-alerte\">Urgence</span> : <span class=\"kw-alerte\">hospitalisation</span> en milieu spécialisé (avec ou sans consentement) ; <span class=\"kw-ttt\">antipsychotique de 2ᵉ génération</span> ; assurer la <strong>sécurité du bébé</strong></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes · 353 — Risque et conduite suicidaire</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> psychiatrique :</strong> la <span class=\"kw-etio\">psychose puerpérale</span> (épisode psychotique bref, épisode maniaque du post-partum) est une <span class=\"kw-alerte\">urgence thérapeutique</span> avec <span class=\"kw-alerte\">risque suicidaire et d'infanticide</span>.<br><strong>Délai :</strong> épisode psychotique bref dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">≤ 4 premières semaines</span>, pic à <span class=\"kw-chiffre\">J10</span> ; début <span class=\"kw-clinique\">brutal</span>.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">hospitalisation en urgence</span> en milieu spécialisé (avec ou sans consentement) et <span class=\"kw-alerte\">mise en sécurité du bébé</span>.</p>","hospit":"<p><strong>Pas de PEC spécifique :</strong> <span class=\"kw-etio\">post-partum blues</span>, état <span class=\"kw-def\">physiologique</span>.<br><strong>Ambulatoire :</strong> <span class=\"kw-etio\">EDC du post-partum</span> d'intensité <span class=\"kw-clinique\">légère à moyenne</span> — prise en charge précoce ambulatoire le plus souvent suffisante.<br><strong>Unité mère-bébé (UMB/UME) :</strong> pathologie <span class=\"kw-alerte\">sévère</span> et/ou environnement social précaire, <span class=\"kw-alerte\">idées suicidaires</span>, <span class=\"kw-etio\">caractéristiques psychotiques</span> — objectifs : soin de la mère, travail du lien mère-enfant, prévention des troubles du développement de l'enfant.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span> (milieu spécialisé) :</strong> <span class=\"kw-etio\">psychose puerpérale</span>, <span class=\"kw-etio\">épisode maniaque du post-partum</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Idées suicidaires</span> et <span class=\"kw-alerte\">risque d'infanticide</span> (caractéristiques psychotiques)</li><li><span class=\"kw-etio\">Idées délirantes polymorphes</span> centrées sur le bébé (négation de filiation, persécution)</li><li><span class=\"kw-clinique\">Symptômes confusionnels</span> / tableau pseudo-confusionnel</li><li>Début <span class=\"kw-clinique\">brutal</span> (évoque épisode maniaque ou psychotique bref du post-partum)</li><li><span class=\"kw-clinique\">Phobies d'impulsion</span>, craintes de faire du mal au bébé, évitement du <span class=\"kw-def\">contact</span> avec le bébé</li><li>Post-partum blues <span class=\"kw-alerte\">trop long (> 15 jours)</span> ou trop sévère → FR de trouble psychiatrique du post-partum</li><li>Souffrance du bébé : <span class=\"kw-clinique\">agitation</span> ou <span class=\"kw-clinique\">apathie</span>, troubles du <span class=\"kw-clinique\">sommeil</span>/<span class=\"kw-clinique\">alimentation</span>, retard psychomoteur</li></ul>","principes":"<p>La prise en charge dépend du tableau et privilégie la <span class=\"kw-alerte\">sécurité de la mère et du bébé</span> sur l'ensemble de la <span class=\"kw-def\">période périnatale</span> (conception → 1re année de l'enfant).</p><p><strong>Post-partum blues</strong></p><ul><li>État adaptatif <span class=\"kw-def\">physiologique</span> — <span class=\"kw-ttt\">pas de traitement</span>, réassurance de l'entourage</li><li>Surveiller : si <span class=\"kw-alerte\">trop long ou trop sévère</span> → FR de trouble psychiatrique du post-partum</li></ul><p><strong>EDC du post-partum</strong></p><p>Prise en charge précoce et ambulatoire le plus souvent suffisante</p><ul><li><span class=\"kw-ttt\">ISRS</span> + <span class=\"kw-ttt\">psychothérapie</span> (de soutien ou <span class=\"kw-ttt\">thérapie cognitivo-comportementale</span>)</li><li><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-ttt\">unité mère-enfant</span> si forme <span class=\"kw-alerte\">sévère</span>, idées suicidaires ou caractéristiques psychotiques</li></ul><p><strong>Épisode maniaque du post-partum</strong></p><p><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li><span class=\"kw-ttt\">Thymorégulateur</span> ± <span class=\"kw-ttt\">antipsychotique de 2e génération</span> si caractéristiques psychotiques</li><li><span class=\"kw-ttt\">Séparation initiale mère-enfant</span> puis unité mère-bébé ; <span class=\"kw-ttt\">arrêt de l'allaitement</span></li><li><span class=\"kw-ttt\">ECT</span> si <span class=\"kw-alerte\">risque suicidaire et d'infanticide</span></li></ul><p><strong>Épisode psychotique bref (psychose puerpérale)</strong></p><ul><li><span class=\"kw-alerte\">Urgence thérapeutique</span> : <span class=\"kw-alerte\">hospitalisation</span> en milieu spécialisé (avec ou sans consentement)</li><li><span class=\"kw-ttt\">Antipsychotique de 2e génération</span> instauré précocement</li><li>Assurer la <span class=\"kw-alerte\">sécurité du bébé</span></li></ul><p><strong>Psychotropes & <span class=\"kw-ci\">grossesse</span> (ATCD psychiatrique)</strong></p><ul><li><span class=\"kw-ttt\">Posologie minimale efficace</span> ; éviter la prescription <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 premiers mois</span> (risque <span class=\"kw-ci\">tératogène</span>)</li><li><span class=\"kw-ci\">Acide valproïque absolument interdit</span> pendant la <span class=\"kw-ci\">grossesse</span> et en 1re intention chez toute femme en âge de procréer</li><li><span class=\"kw-alerte\">Ne pas arrêter brutalement</span> un traitement à la découverte de la <span class=\"kw-ci\">grossesse</span> (risque de <span class=\"kw-ttt\">sevrage</span> / <span class=\"kw-alerte\">décompensation</span>)</li><li>En cas de doute → avis du <span class=\"kw-ttt\">CRAT</span> (centre de référence des agents tératogènes)</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Dépistage</span> :</strong> le plus précoce possible (médecin traitant, obstétricien, sage-femme, PMI, psychiatre) ; <span class=\"kw-ttt\">entretien prénatal précoce</span> systématique au <span class=\"kw-chiffre\">4e mois</span> de <span class=\"kw-ci\">grossesse</span>.<br><strong>Vigilance EDC du post-partum :</strong> <span class=\"kw-alerte\">sous-diagnostiqué</span> (<span class=\"kw-chiffre\">50 %</span> non diagnostiquées) ; survient <span class=\"kw-chiffre\">≤ 1 an</span>, pic à <span class=\"kw-chiffre\">3-6 semaines</span>.<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> EDC du post-partum = FR d'<span class=\"kw-clinique\">évolution</span> vers un <span class=\"kw-etio\">trouble bipolaire</span> et de <span class=\"kw-etio\">récidive dépressive</span> (<span class=\"kw-chiffre\">> 25 %</span>).<br><strong>Nouveau-né :</strong> <span class=\"kw-def\">surveillance</span> des <span class=\"kw-clinique\">troubles néonataux transitoires</span> si traitement psychotrope, et des <span class=\"kw-clinique\">interactions précoces</span> mère-enfant.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Symptômes psychiques aigus du post-partum — Période périnatale : conception → 1re année de l'enfant","detail":"<h4>CAT — Trouble psychique du post-partum — Orientation devant des symptômes psychiques du post-partum</h4>","branches":[{"to":"q-grav","label":"Évaluer la gravité","color":"blue"}]},{"id":"q-grav","kind":"decision","label":"Signes de gravité ? — Idées suicidaires/infanticide · idées délirantes · confusion · début brutal","branches":[{"to":"q-blues","label":"Non","color":"green"},{"to":"q-confusion","label":"Oui","color":"red"}]},{"id":"q-blues","kind":"decision","label":"Symptômes transitoires précoces ? — <span class=\"kw-chiffre\">J2</span>-J5, pic au 3e jour, durée < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>10</span> jours</span>, labilité émotionnelle","branches":[{"to":"t-blues","label":"Oui","color":"green"},{"to":"q-edc-sev","label":"Non","color":"amber"}]},{"id":"t-blues","kind":"terminal","label":"Post-partum blues","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fatigue</span>, <span class=\"kw-clinique\">labilité émotionnelle</span> (dysphorie), <span class=\"kw-clinique\">crises de larmes</span>, <span class=\"kw-clinique\">irritabilité</span></li><li>Apparition <span class=\"kw-chiffre\">J2-J5</span>, pic au <span class=\"kw-chiffre\">3e jour</span>, durée <span class=\"kw-chiffre\">1-10 jours</span></li></ul><h4>Conduite</h4><ul><li>État <span class=\"kw-def\">physiologique</span> — <span class=\"kw-ttt\">pas de traitement</span>, réassurance de l'entourage</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Si <span class=\"kw-alerte\">> 15 jours</span> ou trop sévère → FR de trouble psychiatrique, réévaluer (EDC du post-partum ?)</li></ul>"},{"id":"q-edc-sev","kind":"decision","label":"EDC du post-partum sévère ? — Idées suicidaires ou caractéristiques psychotiques","branches":[{"to":"t-edc-ambu","label":"Non — léger/moyen","color":"amber"},{"to":"t-umb","label":"Oui","color":"red"}]},{"id":"t-edc-ambu","kind":"terminal","label":"EDC du post-partum — ambulatoire","color":"amber","detail":"<h4>Clinique</h4><ul><li>Humeur triste, <span class=\"kw-clinique\">culpabilité</span> (« j'ai tout pour être heureuse »), sentiment d'incapacité maternelle</li><li>Survenue <span class=\"kw-chiffre\">≤ 1 an</span>, pic à <span class=\"kw-chiffre\">3-6 semaines</span> ; intensité <span class=\"kw-clinique\">légère à moyenne</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">ISRS</span> + <span class=\"kw-ttt\">psychothérapie</span> (de soutien ou <span class=\"kw-ttt\">TCC</span>)</li><li>Prise en charge précoce <span class=\"kw-ttt\">ambulatoire</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>FR d'<span class=\"kw-clinique\">évolution</span> vers un <span class=\"kw-etio\">trouble bipolaire</span> ; impact sur <span class=\"kw-clinique\">les</span> interactions et le neurodéveloppement de l'enfant</li></ul>"},{"id":"t-umb","kind":"terminal","label":"EDC sévère → unité mère-bébé","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Idées noires et suicidaires</span>, <span class=\"kw-etio\">caractéristiques psychotiques</span> (risque suicidaire et d'infanticide), possible mélancolie délirante</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-ttt\">unité mère-enfant (UMB)</span> : soin de la mère, travail du lien mère-enfant</li><li><span class=\"kw-ttt\">ISRS</span> + psychothérapie</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-alerte\">Risque suicidaire</span> et sécurité du bébé</li></ul>"},{"id":"q-confusion","kind":"decision","label":"Tableau pseudo-confusionnel ?","branches":[{"to":"t-bilan","label":"Oui","color":"amber"},{"to":"t-psychose","label":"Non","color":"red"}]},{"id":"t-bilan","kind":"terminal","label":"Bilan complémentaire en urgence","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-ttt\">Bilan en urgence</span> pour éliminer une cause non psychiatrique : <span class=\"kw-etio\">thrombophlébite cérébrale</span>, <span class=\"kw-etio\">endométrite</span>/infection, <span class=\"kw-etio\">rétention placentaire</span>, <span class=\"kw-etio\">intoxication par substance psychoactive</span></li></ul><h4>Conduite</h4><ul><li>Si cause organique éliminée → <span class=\"kw-etio\">psychose puerpérale</span> : <span class=\"kw-alerte\">hospitalisation</span> psychiatrique en <span class=\"kw-alerte\">urgence</span></li></ul>"},{"id":"t-psychose","kind":"terminal","label":"Psychose puerpérale — urgence","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">Idées délirantes polymorphes</span> centrées sur le bébé (négation de filiation, persécution), <span class=\"kw-clinique\">labilité émotionnelle</span>, début <span class=\"kw-clinique\">brutal</span></li><li>Pic à <span class=\"kw-chiffre\">J10</span>, dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">≤ 4 premières semaines</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence thérapeutique</span> : <span class=\"kw-ttt\">hospitalisation en milieu spécialisé</span> (avec ou sans consentement)</li><li><span class=\"kw-alerte\">Assurer la sécurité du bébé</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antipsychotique de 2e génération</span> instauré précocement</li><li>Épisode maniaque associé : <span class=\"kw-ttt\">thymorégulateur</span> ± antipsychotique 2e gén, <span class=\"kw-ttt\">ECT</span> si <span class=\"kw-alerte\">risque suicidaire/infanticide</span>, arrêt de l'<span class=\"kw-ci\">allaitement</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Évolution</span> vers un <span class=\"kw-etio\">trouble bipolaire</span> (majorité) ou une <span class=\"kw-etio\">schizophrénie</span> ; récidive lors d'une <span class=\"kw-ci\">grossesse</span> ultérieure <span class=\"kw-chiffre\">20-30 %</span></li></ul>"}]},"cards":[{"i":"060d42f69dbf","n":69,"o":"69-1","u":"Définition","t":"Connaître la définition des principaux troubles concernés, y compris le post-partum blues et le trouble de stress post-traumatique en lien avec la grossesse","q":"Définition du trouble de stress post-traumatique (TSPT) lié à la grossesse.","a":"<p>C'est un trouble de stress post-traumatique qui fait suite à un <strong>accouchement vécu comme traumatique</strong> (par exemple, accouchement en urgence, complications obstétricales).</p><ul><li>Les symptômes classiques incluent des <strong>flash-backs</strong>, des conduites d'<strong>évitement</strong> et une <strong>hypervigilance</strong>.</li></ul>"},{"i":"21cad823077f","n":69,"o":"69-1","u":"Définition","t":"Connaître la définition des principaux troubles concernés, y compris le post-partum blues et le trouble de stress post-traumatique en lien avec la grossesse","q":"Définition de l'épisode dépressif caractérisé (EDC) du post-partum.","a":"<p>C'est un <strong>épisode dépressif caractérisé</strong> qui survient spécifiquement dans l'<strong>année</strong> suivant l'accouchement.</p><ul><li>Le post-partum est la période de risque maximal de dépression chez la femme.</li></ul>"},{"i":"8886dc6b4808","n":69,"o":"69-1","u":"Définition","t":"Connaître la définition des principaux troubles concernés, y compris le post-partum blues et le trouble de stress post-traumatique en lien avec la grossesse","q":"Définition du déni de grossesse.","a":"<p>Le déni de grossesse se caractérise par l'absence de prise de conscience de la grossesse.</p><ul><li>Le <strong>déni partiel</strong> correspond à la non-prise de conscience de la grossesse à partir de <strong>≥ 22 SA</strong>.</li><li>Le <strong>déni total</strong> correspond à la non-prise de conscience de la grossesse jusqu'à l'<strong>accouchement</strong>.</li><li>Il doit être différencié de la dissimulation volontaire de la grossesse.</li></ul>"},{"i":"cb7de8383245","n":69,"o":"69-1","u":"Définition","t":"Connaître la définition des principaux troubles concernés, y compris le post-partum blues et le trouble de stress post-traumatique en lien avec la grossesse","q":"Définition de la psychose puerpérale.","a":"<p>La psychose puerpérale regroupe les <strong>épisodes psychotiques brefs</strong> et les <strong>épisodes thymiques</strong> (dépression ou manie) avec caractéristiques psychotiques survenant dans le post-partum.</p><ul><li>Il s'agit d'une <strong>urgence psychiatrique</strong>.</li></ul>"},{"i":"eb51584c9e75","n":69,"o":"69-1","u":"Définition","t":"Connaître la définition des principaux troubles concernés, y compris le post-partum blues et le trouble de stress post-traumatique en lien avec la grossesse","q":"Définition du post-partum blues (ou baby blues).","a":"<p>Il s'agit d'un état <strong>adaptatif physiologique transitoire</strong> lié aux réaménagements affectifs de l'accouchement.</p><ul><li>Il survient généralement entre <strong>J2 et J5</strong> après la naissance, avec un pic au <strong>3e jour</strong>.</li><li>Il ne s'agit <strong>PAS</strong> d'un trouble psychiatrique.</li></ul>"}]};